import java.util.*;

public class Main {
    static long[] sums(long[] a, int from, int to) {
        long[] r = new long[1 << (to - from)];
        int size = 1;
        for (int i = from; i < to; i++) {
            for (int j = 0; j < size; j++) r[size + j] = r[j] + a[i];
            size *= 2;
        }
        return r;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long S = sc.nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextLong();
        int h = n / 2;
        HashMap<Long, Integer> cnt = new HashMap<>();
        for (long v : sums(a, h, n)) cnt.merge(v, 1, Integer::sum);
        long ans = 0;
        for (long v : sums(a, 0, h)) ans += cnt.getOrDefault(S - v, 0);
        System.out.println(ans);
    }
}

