#include <bits/stdc++.h>
using namespace std;
vector<long long> sums(const vector<long long>& a, int from, int to) {
    vector<long long> r(1, 0);
    for (int i = from; i < to; i++) {
        size_t m = r.size();
        for (size_t j = 0; j < m; j++) {
            long long v = r[j] + a[i];
            r.push_back(v);
        }
    }
    return r;
}

int main() {
    int n;
    long long S;
    cin >> n >> S;
    vector<long long> a(n);
    for (auto &v : a) cin >> v;
    int h = n / 2;
    vector<long long> right = sums(a, h, n), left = sums(a, 0, h);
    sort(right.begin(), right.end());
    long long ans = 0;
    for (long long v : left) {
        auto range = equal_range(right.begin(), right.end(), S - v);
        ans += range.second - range.first;
    }
    cout << ans << endl;
    return 0;
}
